rules:
// Sprawdza sterownik VAV Nefryt wg layoutu (REGULACJA GLOWNA / NAWIEW / WYCIAG).
// p = odczyt biezacy, prev = odczyt poprzedni. Wymiary kanalow w METRACH (0,75 x 0,15).
const tol=(a,b,proc,abs)=>Math.abs(a-b)<=Math.abs(a)*proc/100+(abs||1);
const A_sup=p.SupplyH*p.SupplyV;                 // m2
const A_ext=p.ReturnH*p.ReturnV;

// 1) przeplyw = suma predkosci x przekroj x 3600 (blok Multiply2 w sterowniku)
const q_sup_exp=p.SpeedSupply*A_sup*3600;
const q_ext_exp=p.SpeedReturn*A_ext*3600;

// 2) rampa CO2: od (nastawa - PropBand) do nastawy, z MinFlow do MaxFlow (LinearGraph, Limited)
const x1=p.CO2Setpoint-p.CO2PropBand;
const ramp=Math.min(1,Math.max(0,(p.CO2-x1)/(p.CO2PropBand||1)));
const sp_auto=p.MinFlow+ramp*(p.MaxFlow-p.MinFlow);

// 3) tryb (NumericSelect): 1-AUTO, 2-MIN, 3-MAX, 4-OFF
const m=Number(p.Mode);
const sp_sup=m===1?sp_auto:m===2?p.MinFlow:m===3?p.MaxFlow:0;
const sp_ext=sp_sup-p.Diff;                      // nastawa nadazna za nawiewem

// Regulacje oceniamy dopiero, gdy uklad sie ustabilizowal, bo przepustnica
// dojezdza do nowej nastawy kilkadziesiat sekund - inaczej ROZJAZD miga stale.
const stoi=(a,b)=>tol(a,b,1,5);
const ustalone=stoi(p.FlowSupply,prev.FlowSupply)&&stoi(p.FlowReturn,prev.FlowReturn);
const kraniec=(poz)=>poz>=99||poz<=1;            // przepustnica na ograniczniku
const pomin=(poz)=>!ustalone||kraniec(poz);

const r=[
 ['przeplyw nawiewu = predkosc x przekroj x 3600', q_sup_exp, p.FlowSupply, tol(q_sup_exp,p.FlowSupply,3)],
 ['przeplyw wyciagu = predkosc x przekroj x 3600', q_ext_exp, p.FlowReturn, tol(q_ext_exp,p.FlowReturn,3)],
 ['nastawa nawiewu wg rampy CO2 i trybu', sp_sup, p.FlowSupply,
   pomin(p.PositionSupply)||tol(sp_sup,p.FlowSupply,10,20)],
 ['wyciag nadaza za nawiewem (nawiew - DIFF)', sp_ext, p.FlowReturn,
   pomin(p.PositionReturn)||tol(sp_ext,p.FlowReturn,10,20)],
 ['roznica nawiew-wyciag = DIFF', p.Diff, p.FlowSupply-p.FlowReturn,
   pomin(p.PositionSupply)||pomin(p.PositionReturn)||tol(p.Diff,p.FlowSupply-p.FlowReturn,10,25)],
];

// kontrole konfiguracji - lapia zla nastawe, nie regulacje
if(p.SupplyH>10||p.SupplyV>10||p.ReturnH>10||p.ReturnV>10)
 r.push(['wymiary kanalu w METRACH (wpisano mm?)', 1, 0, false]);
if(p.MinFlow>=p.MaxFlow) r.push(['MinFlow < MaxFlow', 1, 0, false]);
if(p.CO2PropBand<=0) r.push(['PropBand > 0', 1, 0, false]);
if(m===4) r.push(['UWAGA: tryb OFF (4) - regulacja wylaczona', 1, 0, false]);
return r;
